def test_surface_case1():
    surf=prepare_surface_case1()
    umin,umax=nurbs_interval(surf.knot_u, surf.order_u-1)
    vmin,vmax=nurbs_interval(surf.knot_v, surf.order_v - 1)
    _u,_v=0.4, 0.75
    u=umin+(umax-umin)*_u
    v = vmin + (vmax - vmin) * _v
